import os
import sys
import tempfile
import threading

sys.path.insert(0, "/mnt/c/claude_gsb/cla04/solverA/task014")
from weighted_batcher import (  # noqa: E402
    append_metrics,
    compact_metrics,
    prune_metrics,
    rotate_metrics,
    snapshot_diff_metrics,
    snapshot_metrics,
)

d = tempfile.mkdtemp()
pc = os.path.join(d, "log")
for i in range(20):
    append_metrics(pc, '{"i":%d}' % i)
hc1 = snapshot_metrics(pc)
for i in range(20, 40):
    append_metrics(pc, '{"i":%d}' % i)
hc2 = snapshot_metrics(pc)


def count_lines(p):
    try:
        with open(p, "rb") as f:
            return sum(1 for _ in f)
    except OSError as e:
        return f"ERR {e}"


errors = []


def writer():
    try:
        for i in range(40, 400):
            append_metrics(pc, '{"i":%d}' % i)
            if i % 50 == 0:
                rotate_metrics(pc)
            if i % 120 == 0:
                compact_metrics(pc)
            if i % 90 == 0:
                prune_metrics(pc, 200)
    except Exception as e:
        errors.append(e)


def reader():
    try:
        d1 = list(snapshot_diff_metrics(pc, hc1, hc2))
        assert len(d1) == 20, (len(d1), d1[:4], d1[-2:])
    except Exception as e:
        errors.append(e)


wt = threading.Thread(target=writer)
rt = threading.Thread(target=reader)
wt.start(); rt.start(); wt.join(); rt.join()
print("errors:", errors[:1])
print("hc1 copy lines now:", count_lines(pc + ".snap." + hc1))
print("hc2 copy lines now:", count_lines(pc + ".snap." + hc2))
print(sorted(os.listdir(d)))

